CREATE OR REPLACE FUNCTION public.developer_fees_valid(_fees jsonb,_deal text,_price numeric) RETURNS boolean LANGUAGE plpgsql IMMUTABLE SET search_path=public AS $$ DECLARE k text; v numeric; c numeric; BEGIN IF _fees IS NULL OR _price IS NULL OR _price<=0 THEN RETURN false; END IF; FOREACH k IN ARRAY ARRAY['form','whatsapp','phone'] LOOP IF jsonb_typeof(_fees->k) IS DISTINCT FROM 'number' OR jsonb_typeof(_fees->'caps'->k) IS DISTINCT FROM 'number' THEN RETURN false; END IF; v:=(_fees->>k)::numeric; c:=(_fees->'caps'->>k)::numeric; IF v IS NULL OR v<=0 OR v>500 OR c IS NULL OR c<=0 OR c<>trunc(c) THEN RETURN false; END IF; END LOOP; IF jsonb_typeof(_fees->'closing'->'value') IS DISTINCT FROM 'number' THEN RETURN false; END IF; v:=(_fees->'closing'->>'value')::numeric; IF v IS NULL OR v<=0 THEN RETURN false; END IF; IF _fees->'closing'->>'type'='percent' THEN RETURN CASE WHEN _deal='rent' THEN v BETWEEN 10 AND 100 ELSE v BETWEEN 0.2 AND 2 END; END IF; RETURN COALESCE(_fees->'closing'->>'type'='fixed',false); EXCEPTION WHEN OTHERS THEN RETURN false; END $$;
CREATE OR REPLACE FUNCTION public.validate_developer_listing_commissions() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE f jsonb; is_developer boolean; BEGIN is_developer:=NEW.developer_project_id IS NOT NULL OR NEW.features->>'publisher_type'='developer' OR public.has_role(NEW.workspace_owner_id,'developer'); IF TG_OP='UPDATE' THEN is_developer:=is_developer OR OLD.developer_project_id IS NOT NULL OR OLD.features->>'publisher_type'='developer'; END IF; IF NEW.is_published AND COALESCE(is_developer,false) THEN IF NEW.developer_project_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.developer_projects p WHERE p.id=NEW.developer_project_id AND p.workspace_owner_id=NEW.workspace_owner_id) THEN RAISE EXCEPTION 'developer_project_workspace_mismatch'; END IF; IF NEW.affiliate_tier3_type IS DISTINCT FROM 'fixed' THEN RAISE EXCEPTION 'developer_phone_fee_must_be_fixed'; END IF; f:=jsonb_build_object('form',NEW.affiliate_tier1_amount,'whatsapp',NEW.affiliate_tier2_amount,'phone',NEW.affiliate_tier3_amount,'caps',NEW.contact_options->'lead_daily_limits','closing',jsonb_build_object('type',NEW.affiliate_tier4_type,'value',NEW.affiliate_tier4_amount)); IF NOT public.developer_fees_valid(f,COALESCE(NEW.deal_type,'sale'),NEW.asking_price) THEN RAISE EXCEPTION 'developer_commissions_required'; END IF; END IF; RETURN NEW; END $$;
DO $patch$ DECLARE body text; BEGIN SELECT pg_get_functiondef('public.publish_developer_project(uuid,text)'::regprocedure) INTO body; body:=replace(body,'affiliate_tier3_amount=EXCLUDED.affiliate_tier3_amount,affiliate_tier4_type','affiliate_tier3_amount=EXCLUDED.affiliate_tier3_amount,affiliate_tier3_type=EXCLUDED.affiliate_tier3_type,affiliate_approved_at=COALESCE(listings.affiliate_approved_at,EXCLUDED.affiliate_approved_at),affiliate_tier4_type'); body:=replace(body,'FOR u IN SELECT value FROM jsonb_array_elements(p.apartments) LOOP key:=','FOR u IN SELECT value FROM jsonb_array_elements(p.apartments) LOOP IF NULLIF(u->>''source_unit_id'','''') IS NULL THEN RAISE EXCEPTION ''developer_unit_identity_required''; END IF; key:='); EXECUTE body; END $patch$;